example.code:
// Create ports
var port1 = new IpPort(8080);
var port2 = IpPort.Parse("443");
var port3 = IpPort.Http;

// Properties
bool isWellKnown = port1.IsWellKnown;     // false (8080 > 1023)
bool isRegistered = port1.IsRegistered;   // true (1024-49151)
bool isDynamic = port1.IsDynamic;         // false

// Implicit conversions
ushort value = port1;  // 8080
IpPort port4 = 3000;   // implicit from int

// Well-known ports
var http = IpPort.Http;        // 80
var https = IpPort.Https;      // 443
var ssh = IpPort.Ssh;          // 22

// Create IPv4 addresses
var localhost = Ipv4Address.Loopback;
var address = Ipv4Address.Parse("192.168.1.1");
var fromUint = new Ipv4Address(0xC0A80101u);

// Network calculations
var network = address.GetNetwork(24); // 192.168.1.0
var broadcast = address.GetBroadcast(24); // 192.168.1.255
bool isInNetwork = address.IsInNetwork(network, 24);

// JSON serialization works automatically
string json = JsonSerializer.Serialize(address);
Ipv4Address deserialized = JsonSerializer.Deserialize<Ipv4Address>(json);

var address = Ipv4Address.Parse("192.168.1.100");
var network = Ipv4Address.Parse("192.168.1.0");
bool isInNetwork = address.IsInNetwork(network, 24); // Returns true

// Create configurations
var config = new Ipv4Configuration(
    address: "192.168.1.100",
    prefixLength: 24,
    gateway: "192.168.1.1"
);

// Alternative creation methods
var config2 = Ipv4Configuration.Parse("192.168.1.100/24 gw 192.168.1.1");
var config3 = Ipv4Configuration.FromNetwork(
    network: "192.168.1.0/24",
    hostAddress: "192.168.1.100",
    gateway: "192.168.1.1"
);

// Access properties
var network = config.Network;           // 192.168.1.0/24
var broadcast = config.BroadcastAddress; // 192.168.1.255
bool isValid = config.IsValid();        // true if gateway is in network

// String representation
Console.WriteLine(config); // "192.168.1.100/24 gw 192.168.1.1"

// Create endpoints
var endpoint1 = new Ipv4Endpoint("192.168.1.100", 8080);
var endpoint2 = Ipv4Endpoint.Parse("192.168.1.100:443");
var endpoint3 = new Ipv4Endpoint(Ipv4Address.Loopback, IpPort.Http);

// From IPEndPoint
var ipEndPoint = new IPEndPoint(IPAddress.Parse("10.0.0.1"), 3000);
Ipv4Endpoint endpoint4 = ipEndPoint;

// To IPEndPoint
IPEndPoint converted = endpoint1;

// Properties
var address = endpoint1.Address;  // 192.168.1.100
var port = endpoint1.Port;        // 8080

// String representation
string str = endpoint1.ToString(); // "192.168.1.100:8080"

// Create networks
var network = Ipv4Network.Parse("192.168.1.0/24");
var network2 = new Ipv4Network(Ipv4Address.Parse("10.0.0.0"), 8);

// Network properties
var networkAddr = network.NetworkAddress;    // 192.168.1.0
var broadcast = network.BroadcastAddress;    // 192.168.1.255
var hostCount = network.HostCount;           // 254
var totalCount = network.TotalAddressCount;  // 256

// Check if address is in network
bool contains = network.Contains(Ipv4Address.Parse("192.168.1.100")); // true

// Check network overlap
var other = Ipv4Network.Parse("192.168.1.128/25");
bool overlaps = network.Overlaps(other); // true

// Enumerate addresses
foreach (var addr in network.GetAddresses())
{
    Console.WriteLine(addr);
}

var network = Ipv4Network.Parse("192.168.1.0/24");
var subnets = network.Subnet(26); // Split into /26 subnets
// Returns: 192.168.1.0/26, 192.168.1.64/26, 192.168.1.128/26, 192.168.1.192/26

// Create MAC addresses
var mac1 = MacAddress.Parse("AA:BB:CC:DD:EE:FF");
var mac2 = MacAddress.Parse("AA-BB-CC-DD-EE-FF");
var mac3 = MacAddress.Parse("AABBCCDDEEFF");
var mac4 = MacAddress.From(new byte[] { 0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0xFF });

// Properties
bool isBroadcast = mac1.IsBroadcast;
bool isMulticast = mac1.IsMulticast;
bool isUnicast = mac1.IsUnicast;
byte[] bytes = mac1.GetBytes();

// String output (canonical colon format)
string str = mac1.ToString(); // "AA:BB:CC:DD:EE:FF"
